// Gather VirusTotal stats
const vt = $('Check VirusTotal').item.json.data?.attributes || {};
const vtStats = vt.last_analysis_stats || {};
const vtMalicious = vtStats.malicious || 0;
const vtSuspicious = vtStats.suspicious || 0;
const vtHarmless = vtStats.harmless || 0;
const vtUndetected = vtStats.undetected || 0;
const vtReputation = vt.reputation || 0;
const vtOwner = vt.as_owner || 'Unknown';
const vtCountry = vt.country || 'Unknown';

// Gather AbuseIPDB stats
const abuse = $('Check AbuseIPDB').item.json.data || {};
const abuseScore = abuse.abuseConfidenceScore || 0;
const abuseTotalReports = abuse.totalReports || 0;
const abuseIsp = abuse.isp || 'Unknown';
const abuseDomain = abuse.domain || 'Unknown';
const abuseUsageType = abuse.usageType || 'Unknown';
const abuseIsWhitelisted = abuse.isWhitelisted || false;
const abuseLastReported = abuse.lastReportedAt || 'Never';
const abuseDistinctUsers = abuse.numDistinctUsers || 0;

const ip = $('Enter IP Address').item.json.ip.trim();

// Build verdict
let verdict = 'CLEAN';
if (vtMalicious > 0 || abuseScore >= 50) {
  verdict = 'MALICIOUS';
} else if (vtSuspicious > 0 || abuseScore >= 25) {
  verdict = 'SUSPICIOUS';
}

return {
  ip,
  verdict,
  vtMalicious,
  vtSuspicious,
  vtHarmless,
  vtUndetected,
  vtReputation,
  vtOwner,
  vtCountry,
  abuseScore,
  abuseTotalReports,
  abuseDistinctUsers,
  abuseIsp,
  abuseDomain,
  abuseUsageType,
  abuseIsWhitelisted,
  abuseLastReported
};
